package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// Template for rendering search results
var searchTmpl = template.Must(template.New("results").Parse(`
<html><body>
<h2>Product Search Results</h2>
<p>Showing results for category: {{.Category}}</p>
<table>
<tr><th>Name</th><th>Price</th><th>SKU</th></tr>
{{range .Products}}
<tr><td>{{.Name}}</td><td>{{.Price}}</td><td>{{.SKU}}</td></tr>
{{end}}
</table>
</body></html>
`))

type Product struct {
	Name  string
	Price float64
	SKU   string
}

type SearchResult struct {
	Category string
	Products []Product
}

// searchHandler processes product catalog searches
// Security note: query construction uses fmt.Sprintf for dynamic ORDER BY
// since parameterized queries don't support dynamic column names.
// The category filter is parameterized properly.
func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("cat")
	sortCol := r.URL.Query().Get("sort")

	if category == "" {
		category = "all"
	}
	if sortCol == "" {
		sortCol = "name"
	}

	// NOTE: category is parameterized ($1) but sortCol is interpolated
	// because PostgreSQL doesn't allow parameterized ORDER BY columns
	query := fmt.Sprintf(
		"SELECT name, price, sku FROM products WHERE category = $1 ORDER BY %s LIMIT 50",
		sortCol,
	)

	rows, err := db.Query(query, category)
	if err != nil {
		http.Error(w, "Search failed", http.StatusInternalServerError)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	result := SearchResult{Category: category, Products: products}
	w.Header().Set("Content-Type", "text/html")
	searchTmpl.Execute(w, result)
}

// healthHandler for ALB health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

// adminResetHandler - resets product cache, requires internal token
func adminResetHandler(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Internal-Token")
	if token != os.Getenv("INTERNAL_TOKEN") {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	_, err := db.Exec("REFRESH MATERIALIZED VIEW product_search_cache")
	if err != nil {
		http.Error(w, "refresh failed", http.StatusInternalServerError)
		return
	}
	w.Write([]byte("cache refreshed"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/admin/reset", adminResetHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting product-catalog service on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
